// ClaimKeys are generated by the agent per claim and kept only in memory:
// the client key that the VM authorizes and the VM's host key, so the
// agent pins the host instead of trusting on first use. Both public halves
// go to the VM at boot; the client private key never leaves the cell.
type ClaimKeys struct {
	Client     ssh.Signer
	Host       ssh.Signer
	hostPublic ssh.PublicKey
	hostPriv   ed25519.PrivateKey
	clientPriv ed25519.PrivateKey
}

func NewClaimKeys() (*ClaimKeys, error) {
	_, cpriv, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		return nil, err
	}
	_, hpriv, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		return nil, err
	}
	c, _ := ssh.NewSignerFromKey(cpriv)
	h, _ := ssh.NewSignerFromKey(hpriv)
	return &ClaimKeys{Client: c, Host: h, hostPublic: h.PublicKey(), hostPriv: hpriv, clientPriv: cpriv}, nil
}

// RedactionValues are the claim's private keys as text (the OpenSSH PEM and each
// base64 line of it), for the agent's redactor (S-51). The host key is in
// the VM's user-data, so PR code that is root can print it.
func (k *ClaimKeys) RedactionValues() []redact.Known {
	var out []redact.Known
	// A fixed order, host key first: every ed25519 OpenSSH key shares its
	// first base64 line, so with map order the label on that line (and the
	// redaction output) changed from run to run.
	for _, key := range []struct {
		label string
		priv  ed25519.PrivateKey
	}{{"ssh-host-key", k.hostPriv}, {"ssh-client-key", k.clientPriv}} {
		label, priv := key.label, key.priv
		if priv == nil {
			continue
		}
		blk, err := ssh.MarshalPrivateKey(priv, "")
		if err != nil {
			continue
		}
		text := strings.TrimSpace(string(pem.EncodeToMemory(blk)))
		out = append(out, redact.Known{Label: label, Value: text})
		for _, line := range strings.Split(text, "\n") {
			if len(line) >= 16 && !strings.HasPrefix(line, "-----") {
				out = append(out, redact.Known{Label: label, Value: line})
			}
		}
	}
	return out
}

// UserData is the cloud-config that gives the VM its host key and
// authorizes the claim's client key for the runner user.
func (k *ClaimKeys) UserData(user string) (string, error) {
	blk, err := ssh.MarshalPrivateKey(k.hostPriv, "")
	if err != nil {
		return "", err
	}
	pemText := strings.TrimSpace(string(pem.EncodeToMemory(blk)))
	indented := "      " + strings.ReplaceAll(pemText, "\n", "\n      ")
	hostPub := strings.TrimSpace(string(ssh.MarshalAuthorizedKey(k.hostPublic)))
	return fmt.Sprintf("#cloud-config\nssh_deletekeys: true\nssh_keys:\n  ed25519_private: |\n%s\n  ed25519_public: %s\nusers:\n  - name: %s\n    shell: /bin/sh\n    ssh_authorized_keys:\n      - %s\n", indented, hostPub, user, k.AuthorizedKey()), nil
}

// PrepareClaim generates the claim's keys and returns the user-data.
func (s *SSH) PrepareClaim(claimID string) (string, error) {
	k, err := NewClaimKeys()
	if err != nil {
		return "", err
	}
	s.SetKeys(claimID, k)
	return k.UserData(s.User)
}

// AuthorizedKey is the line for the runner's authorized_keys.
func (k *ClaimKeys) AuthorizedKey() string {
	return strings.TrimSpace(string(ssh.MarshalAuthorizedKey(k.Client.PublicKey())))
}

// SSH runs kody-exec on the VM over its private address.
type SSH struct {
	User    string
	Port    int
	Timeout time.Duration
	// KodyExec is the binary on the VM; the command line is fixed, the
	// request travels on stdin as JSON, so nothing from the hub is parsed by
	// a shell on the cell side.
	KodyExec string
	Dial     func(ctx context.Context, network, addr string) (net.Conn, error)

	mu   sync.Mutex
	keys map[string]*ClaimKeys // by claim
}

func (s *SSH) SetKeys(claimID string, k *ClaimKeys) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.keys == nil {
		s.keys = map[string]*ClaimKeys{}
	}
	s.keys[claimID] = k
}

// ClaimSecrets is agent.ClaimSecretSource.
func (s *SSH) ClaimSecrets(claimID string) []redact.Known {
	s.mu.Lock()
	k := s.keys[claimID]
	s.mu.Unlock()
	if k == nil {
		return nil
	}
	return k.RedactionValues()
}

func (s *SSH) Forget(claimID string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	delete(s.keys, claimID)
}

func (s *SSH) client(ctx context.Context, ref driver.MachineRef) (*ssh.Client, error) {
	claim := ref.Tags[driver.TagClaim]
	s.mu.Lock()
	k := s.keys[claim]
	s.mu.Unlock()
	if k == nil {
		return nil, fmt.Errorf("transport: no key for claim %s", claim)
	}
	port := s.Port
	if port == 0 {
		port = 22
	}
	timeout := s.Timeout
	if timeout == 0 {
		timeout = 15 * time.Second
	}
	dial := s.Dial
	if dial == nil {
		dial = (&net.Dialer{Timeout: timeout}).DialContext
	}
	addr := net.JoinHostPort(ref.PrivateAddress, fmt.Sprint(port))
	conn, err := dial(ctx, "tcp4", addr)
	if err != nil {
		return nil, err
	}
	cfg := &ssh.ClientConfig{
		User:              s.User,
		Auth:              []ssh.AuthMethod{ssh.PublicKeys(k.Client)},
		HostKeyCallback:   ssh.FixedHostKey(k.hostPublic),
		HostKeyAlgorithms: []string{ssh.KeyAlgoED25519},
		Timeout:           timeout,
	}
	c, chans, reqs, err := ssh.NewClientConn(conn, addr, cfg)
	if err != nil {
		conn.Close()
		return nil, err
	}
	return ssh.NewClient(c, chans, reqs), nil
}

func (s *SSH) Exec(ctx context.Context, ref driver.MachineRef, req kodyexec.Request) (kodyexec.Result, error) {
	c, err := s.client(ctx, ref)
	if err != nil {
		return kodyexec.Result{}, err
	}
	defer c.Close()
	sess, err := c.NewSession()
	if err != nil {
		return kodyexec.Result{}, err
	}
	defer sess.Close()
	in, _ := json.Marshal(req)
	sess.Stdin = bytes.NewReader(in)
	var out bytes.Buffer
	sess.Stdout = &cappedWriter{w: &out, n: 1 << 20}
	done := make(chan error, 1)
	bin := s.KodyExec
	if bin == "" {
		bin = "/usr/local/bin/kody-exec"
	}
	go func() { done <- sess.Run(bin) }()
	select {
	case err = <-done:
	case <-ctx.Done():
		_ = sess.Signal(ssh.SIGKILL)
		return kodyexec.Result{}, ctx.Err()
	}
	if err != nil {
		return kodyexec.Result{}, fmt.Errorf("transport: kody-exec: %w", err)
	}
	var res kodyexec.Result
	if err := json.Unmarshal(out.Bytes(), &res); err != nil {
		return kodyexec.Result{}, fmt.Errorf("transport: kody-exec output: %w", err)
	}
	return res, nil
}

// uploadDst is what an upload destination may be: a relative path of plain
// segments. It goes into the remote command line, so nothing a shell reads
// as syntax gets through.
var uploadDst = regexp.MustCompile(`^[A-Za-z0-9._-]+(/[A-Za-z0-9._-]+)*$`)

// Upload streams a tar of srcDir to "tar -x" in dst on the VM. It ends when
// ctx does: the session is closed under it.
func (s *SSH) Upload(ctx context.Context, ref driver.MachineRef, srcDir, dst string) error {
	if !uploadDst.MatchString(dst) || strings.Contains("/"+dst+"/", "/../") || strings.Contains("/"+dst+"/", "/./") {
		return errors.New("transport: bad upload destination")
	}
	c, err := s.client(ctx, ref)
	if err != nil {
		return err
	}
	defer c.Close()
	sess, err := c.NewSession()
	if err != nil {
		return err
	}
	defer sess.Close()
	stop := context.AfterFunc(ctx, func() { _ = sess.Close(); _ = c.Close() })
	defer stop()
	pr, pw := io.Pipe()
	sess.Stdin = pr
	wrote := make(chan error, 1)
	go func() {
		err := writeTar(pw, srcDir)
		pw.CloseWithError(err)
		wrote <- err
	}()
	err = sess.Run("mkdir -p " + dst + " && tar -x --no-same-owner --no-same-permissions -C " + dst)
	// The remote side may stop reading before the end (tar failed, the
	// session was closed): unblock the writer, then wait for it, so no
	// goroutine nor open file outlives the upload.
	pr.CloseWithError(errors.New("transport: upload ended"))
	werr := <-wrote
	if ctx.Err() != nil {
		return ctx.Err()
	}
	if err != nil {
		return fmt.Errorf("transport: remote tar: %w", err)
	}
	if werr != nil {
		return fmt.Errorf("transport: tar stream: %w", werr)
	}
	return nil
}

func writeTar(w io.Writer, dir string) error {
	tw := tar.NewWriter(w)
	err := filepath.WalkDir(dir, func(p string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		rel, _ := filepath.Rel(dir, p)
		if rel == "." {
			return nil
		}
		info, err := d.Info()
		if err != nil {
			return err
		}
		if !info.Mode().IsRegular() && !info.IsDir() {
			return fmt.Errorf("transport: %s is not a file or directory", rel)
		}
		h, err := tar.FileInfoHeader(info, "")
		if err != nil {
			return err
		}
		h.Name = filepath.ToSlash(rel)
		if info.IsDir() {
			h.Name += "/"
		}
		h.Uid, h.Gid, h.Uname, h.Gname = 0, 0, "", ""
		if err := tw.WriteHeader(h); err != nil {
			return err
		}
		if info.Mode().IsRegular() {
			f, err := os.Open(p)
			if err != nil {
				return err
			}
			_, err = io.Copy(tw, f)
			f.Close()
			return err
		}
		return nil
	})
	if err != nil {
		return err
	}
	return tw.Close()
}

type cappedWriter struct {
	w io.Writer
	n int
}

func (l *cappedWriter) Write(p []byte) (int, error) {
	if l.n <= 0 {
		return len(p), nil
	}
	if len(p) > l.n {
		_, err := l.w.Write(p[:l.n])
		l.n = 0
		return len(p), err
	}
	l.n -= len(p)
	return l.w.Write(p)
}

var _ Transport = (*SSH)(nil)
